import json, re, glob, os
IPV4 = re.compile(r"(?<![0-9.])(?:25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])(?:\.(?:25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9]?[0-9])){3}(?![0-9.])")
HOME = re.compile(r"/home/[A-Za-z0-9_-]+")
hits = []
def scan(v, f):
    if isinstance(v, dict):
        for k, i in v.items():
            scan(k, f); scan(i, f)
    elif isinstance(v, list):
        for i in v: scan(i, f)
    elif isinstance(v, str):
        for m in IPV4.finditer(v):
            hits.append((f, m.group(0)))
        if HOME.search(v):
            hits.append((f, "HOMEPATH"))
n = 0
for line in open("data/answers.jsonl", encoding="utf-8"):
    if not line.strip(): continue
    n += 1
    scan(json.loads(line), f"jsonl:{n}")
print("lines:", n, "hits:", len(hits))
for h in hits[:10]: print(h)
